import type { Metadata } from "next";
import { ToolShell, FaqJsonLd, type ToolFaq } from "@/components/marketing/ToolShell";
import { LatencyTestTool } from "@/components/marketing/tools/LatencyTestTool";
import { relatedTools } from "@/lib/tools/catalog";

export const metadata: Metadata = {
  title: "Ping / Latency Test — Measure Your Latency to Nxeon",
  description:
    "Free browser-based ping and latency test. Measure the round-trip time from your device to the Nxeon network in real time — average, best, worst and jitter over multiple samples. No app, no login.",
  alternates: { canonical: "/tools/latency-test" },
};

const faq: ToolFaq[] = [
  {
    q: "What is latency (ping) and why does it matter?",
    a: "Latency is the round-trip time for a small request to travel from your device to a server and back, measured in milliseconds. For game servers, remote desktops, VoIP and fast websites, lower and more consistent latency means a snappier, more responsive experience.",
  },
  {
    q: "How does this test work?",
    a: "Your browser sends a series of tiny requests to a Nxeon endpoint and times how long each round trip takes, then averages them. A warm-up request is discarded first so connection setup doesn't skew the result.",
  },
  {
    q: "What is a good ping?",
    a: "Under ~40 ms is excellent, under ~80 ms is great, and under ~150 ms is fine for most uses. Values depend heavily on your distance to the server and your own connection — someone in Asia-Pacific will see far lower numbers to a Singapore server than someone in North America.",
  },
  {
    q: "Why is my latency high?",
    a: "Physical distance is the biggest factor — light and network hops take time. Wi-Fi, a congested connection, or a VPN also add latency. Nxeon currently serves from a Singapore data center, so this test reflects APAC latency; we don't claim edges we don't have.",
  },
];

export default function Page() {
  return (
    <>
      <FaqJsonLd faq={faq} />
      <ToolShell
        slug="latency-test"
        category="Server tool"
        title="Ping / Latency Test"
        description="Measure the real round-trip latency from your browser to the Nxeon network — average, best, worst and jitter, right now."
        about={[
          {
            heading: "What this latency test measures",
            body: (
              <p>
                It times a burst of small requests from <b>your browser</b> to a Nxeon endpoint and
                reports the average round-trip latency along with the best, worst and jitter (how much
                the ping varies between samples). Because it runs from your device, it reflects the
                latency you would actually experience to a server hosted with us — not a synthetic
                number from a data center near us.
              </p>
            ),
          },
          {
            heading: "Latency, honestly",
            body: (
              <p>
                Nxeon currently runs a single Singapore data center, so this test measures latency to
                that region. If you're in Asia-Pacific you'll see low numbers; farther away, expect
                higher. We'd rather show you the real figure than pretend to a global edge network we
                don't operate.
              </p>
            ),
          },
        ]}
        steps={[
          "Click Start test — no install or login needed.",
          "Your browser sends a series of timed requests to Nxeon.",
          "Read your average latency, plus best, worst and jitter.",
          "Run it again any time to compare across networks or Wi-Fi vs wired.",
        ]}
        faq={faq}
        related={relatedTools("latency-test")}
      >
        <LatencyTestTool />
      </ToolShell>
    </>
  );
}

/**
 * NxLabs — the public + in-portal mod/plugin catalogue read layer.
 *
 * This is a thin, presentation-agnostic layer over the REAL `GameMod` table
 * (seeded rows, enriched by scripts/verify-gamemods.ts). It backs three call
 * sites that must never disagree about what a mod "is":
 *   - app/(marketing)/mods (public browse + detail pages, anonymous-visible)
 *   - app/dashboard/nxlabs (logged-in catalogue with "Add to my server")
 *   - app/sitemap.ts (which detail pages get indexed)
 *
 * Deliberately NOT here: install/uninstall. Those stay exactly where they are
 * — lib/actions-mods.ts's installMod/uninstallMod — this module only reads.
 *
 * HONESTY: a mod only appears in the public/portal catalogue when
 * `active && upstreamOk`. `upstreamOk: false` is scripts/verify-gamemods.ts's
 * (or an admin's manual toggle's) way of saying "no longer supported" — it is
 * excluded rather than shown with a broken badge, matching how
 * lib/actions-mods.ts's getServerMods already filters for the per-server
 * panel. Fields the source never published (gameVersions, license, ...) stay
 * empty and the UI says so — never a guess.
 *
 * REAL PAGINATION (2026-09-19): every comment in this file used to say "small
 * catalogue (~124 rows), the whole set is returned in one shot, filters run
 * client-side" — true when this was hand-seeded, false the moment a real
 * bulk import (scripts/import-modrinth-catalog.ts) landed 32,000+ real
 * Modrinth rows in the `minecraft` family alone. A hard 400-row cap
 * (`CATALOG_LIST_CAP`, since removed) used to mean the other ~31,850 mods in
 * that family were permanently unreachable — no page 2 existed. `queryCatalogMods`
 * replaces `listCatalogMods`/`searchCatalogMods` with real server-side,
 * DB-level pagination (`skip`/`take` + a real `count()`), and search/sort/
 * category-filter all run as part of the SAME query rather than over an
 * in-memory array — see StoreBrowser.tsx's own header comment for why search
 * specifically had to move server-side (its placeholder text promises to
 * search the whole catalogue, not just whatever page happens to be loaded).
 */
import { unstable_cache } from "next/cache";
import { db } from "./db";
import type { GameMod, GamePlan, Prisma } from "@prisma/client";
import { GAME_DISPLAY, type GameFamily } from "./games";
import { paginate } from "./pagination";

/**
 * Real revalidate window for the two whole-catalogue aggregates below
 * (`listCatalogFamilies`, `totalDownloadsFor`) — both are cheap in isolation
 * today (~25-30ms, confirmed live 2026-09-21) but recomputed from scratch on
 * EVERY /mods, /mods/games/[family], /dashboard/nxlabs, and
 * /dashboard/nxlabs/games/[family] request (these pages are `force-dynamic`,
 * so nothing about the route itself is cached). Neither number needs
 * second-by-second freshness — a mod's `featured`/`downloads` values only
 * change via periodic backfill scripts (scripts/verify-gamemods.ts and
 * friends), never a live user action — so wrapping them in Next's real data
 * cache with a 10-minute window cuts real, repeated DB round trips under
 * concurrent traffic without ever showing stale-by-more-than-10-minutes data.
 */
const CATALOG_AGGREGATE_REVALIDATE_SECONDS = 600;

/** Real page size for StoreBrowser — no longer a total-catalogue ceiling. */
const CATALOG_PAGE_SIZE = 24;

export type ModSummary = {
  id: string;
  gameFamily: string;
  gameFamilyLabel: string;
  name: string;
  slug: string;
  category: string;
  source: string;
  iconUrl: string | null;
  description: string | null;
  downloads: number | null;
  featured: boolean;
  paid: boolean;
  verified: boolean;
  impact: string;
  createdAt: string; // ISO — client components get plain data, not Date objects
  /** Real computed average (1-5) from ModRating, null when nobody has rated it yet. */
  avgRating: number | null;
  /** Real count backing avgRating — 0 means "no ratings", never hidden behind a fake avg. */
  ratingCount: number;
  /**
   * The three fields resolveDownloadUrl() needs — carried on the summary too
   * (not just ModDetail) so a browse grid's cards can resolve the same real,
   * per-source download destination as the detail page without a second
   * query: queryCatalogMods already loads the full GameMod row internally,
   * so exposing these costs nothing extra.
   */
  url: string | null;
  sourceId: string | null;
  appliesToVariant: string | null;
  /**
   * The mod's REAL last-shipped timestamp on its own upstream source (ISO —
   * see GameMod.upstreamUpdatedAt's own comment for the confirmed per-source
   * field this is populated from). Null means "not backfilled/verified yet",
   * never a guess — listRecentlyUpdatedMods filters those rows out entirely
   * rather than showing them.
   */
  upstreamUpdatedAt: string | null;
};

export type ModDetail = ModSummary & {
  url: string | null;
  sourceId: string | null;
  license: string | null;
  gameVersions: string[];
  loaders: string[];
  fileBytes: number | null;
  dependencyCount: number;
  serverSide: string | null;
  impactNote: string | null;
  appliesToVariant: string | null;
  verifiedAt: Date | null;
  upstreamOk: boolean;
  upstreamNote: string | null;
  galleryUrls: string[];
  authorName: string | null;
  authorAvatarUrl: string | null;
  /** Source's own longer project-page body (Modrinth's `body`), when backfilled — see GameMod.longDescription. */
  longDescription: string | null;
};

 * The synchronous half of download resolution — every source EXCEPT
 * modrinth/thunderstore resolves with no network call at all (spigotmc's
 * Spiget endpoint is a constructed URL, everything else is just `mod.url`).
 * Returns `undefined` for modrinth/thunderstore specifically, meaning "a
 * live external API call is required" — callers that can't afford to block
 * on that (see StoreBrowser.tsx) use this to render immediately for the
 * ~50% of the catalogue that needs no network at all, and defer the rest to
 * an on-demand client resolve.
 *
 * REAL PERFORMANCE FIX (2026-09-21): `resolveDownloadUrl` below used to be
 * called via `Promise.all` for EVERY mod card in StoreBrowser's grid (up to
 * `CATALOG_PAGE_SIZE`=24 per /mods and /dashboard/nxlabs page load). That was
 * a real, harmless-looking pattern when the catalogue was ~124 hand-seeded
 * rows with few resolvable `sourceId`s; the moment the Modrinth bulk import
 * landed 32,000+ real rows, most default/browse pages became Modrinth-
 * dominated, and every single page load started firing up to 24 concurrent,
 * uncached, un-timed-out HTTPS calls to api.modrinth.com as part of server
 * rendering — measured live against production at 1-2.2s of REAL added
 * latency per page load (see docs/DOCUMENTATION.md's 2026-09-21 entry for
 * the exact numbers), with no upper bound if Modrinth itself is ever slow.
 * Splitting the sync-resolvable 50%+ of sources out, and deferring the
 * network-bound rest to a click-triggered resolve (DownloadButton.tsx +
 * lib/actions-mods.ts's resolveModDownloadAction), removes ALL of that from
 * the server-render critical path — a card the visitor never clicks now
 * costs zero external requests, instead of one whether it's clicked or not.
 */
export function resolveDownloadUrlSync(mod: Pick<GameMod, "source" | "sourceId" | "appliesToVariant" | "url">): ResolvedDownload | undefined {
  const fallback: ResolvedDownload = mod.url ? { url: mod.url, direct: false } : null;
  const id = mod.sourceId ?? "";
  if (!id) return fallback;
  if (mod.source === "modrinth" || mod.source === "thunderstore") return undefined;
  if (mod.source === "spigotmc") {
    // Spiget's own download endpoint 302s to the real jar — genuinely direct, no fetch needed to know that.
    return { url: `https://api.spiget.org/v2/resources/${encodeURIComponent(id)}/download`, direct: true };
  }
  return fallback;
}

/**
 * The uncached live-fetch half of `resolveDownloadUrl` below — pulled out on
 * its own so `unstable_cache` (see `resolveDownloadUrlCached`) wraps ONLY the
 * tiny resolved `{url, direct}` result, never the raw upstream response body.
 *
 * REAL BUG FIX (2026-09-22): this used to rely on `next: { revalidate: 3600 }`
 * on the `fetch` calls themselves — Next's fetch data-cache, which silently
 * refuses to store any response over roughly 2MB and simply re-fetches live
 * on every call instead, with no error or warning. Confirmed live via
 * journalctl: `minecraft-comes-alive-reborn`'s Modrinth `/version` response is
 * 20,035,322 bytes, so it was being re-fetched from api.modrinth.com on
 * EVERY single visit to that mod's detail page with zero caching benefit —
 * and Modrinth's version-list responses routinely run large for mods with
 * many released files, so this wasn't an isolated case. The actual value we
 * need to cache is a couple hundred bytes (`{url, direct}`); caching that
 * directly via `unstable_cache` sidesteps the fetch-cache size ceiling
 * entirely, for every mod regardless of how large its upstream response is.
 */
async function fetchLiveDownload(source: string, sourceId: string): Promise<{ url: string; direct: boolean } | null> {
  const UA = "Nxeon/1.0 (nxlabs-catalog)";
  try {
    if (source === "modrinth") {
      const headers: Record<string, string> = { "User-Agent": UA };
      if (process.env.MODRINTH_API_KEY) headers.Authorization = process.env.MODRINTH_API_KEY;
      const res = await fetch(`https://api.modrinth.com/v2/project/${encodeURIComponent(sourceId)}/version`, {
        headers,
        signal: AbortSignal.timeout(5000),
      });
      if (!res.ok) return null;
      const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
      const v = versions[0];
      const file = v ? (v.files.find((f) => f.primary) ?? v.files[0]) : null;
      return file ? { url: file.url, direct: true } : null;
    }
    if (source === "thunderstore") {
      const [namespace, ...rest] = sourceId.split("-");
      if (!namespace || !rest.length) return null;
      const res = await fetch(`https://thunderstore.io/api/experimental/package/${encodeURIComponent(namespace)}/${encodeURIComponent(rest.join("-"))}/`, {
        headers: { "User-Agent": UA },
        signal: AbortSignal.timeout(5000),
      });
      if (!res.ok) return null;
      const pkg = (await res.json()) as { latest?: { download_url?: string } };
      return pkg.latest?.download_url ? { url: pkg.latest.download_url, direct: true } : null;
    }
  } catch {
    return null;
  }
  return null;
}

const fetchLiveDownloadCached = unstable_cache(fetchLiveDownload, ["mods-catalog:resolveDownloadUrl"], {
  revalidate: 3600,
});

/**
 * The real, authoritative download for a mod detail page. Prefers the
 * source's own direct file URL (same resolution `worker/game-mods.ts` uses to
 * install it) so a visitor gets the actual file, not just a landing page;
 * falls back to the mod's own project/resource page (still the real,
