 * (`AbortSignal.timeout`) so a slow/unresponsive upstream can never hang this
 * past a bounded worst case — there was no timeout at all before 2026-09-21,
 * so a degraded Modrinth/Thunderstore response could block a caller
 * indefinitely. The live fetch itself is cached via `unstable_cache`, not
 * `next: { revalidate }` — see `fetchLiveDownload`'s comment for why.
 */
export async function resolveDownloadUrl(mod: Pick<GameMod, "source" | "sourceId" | "appliesToVariant" | "url">): Promise<ResolvedDownload> {
  const sync = resolveDownloadUrlSync(mod);
  if (sync !== undefined) return sync;

  const fallback: ResolvedDownload = mod.url ? { url: mod.url, direct: false } : null;
  const id = mod.sourceId ?? "";
  const live = await fetchLiveDownloadCached(mod.source, id);
  return live ?? fallback;
}

