class PingManager {
    constructor() {
        this.servers = [];
    }

    getPingClass(ping) {
        if (ping < 100) return 'ping-green';
        if (ping < 200) return 'ping-yellow';
        if (ping < 300) return 'ping-orange';
        return 'ping-red';
    }

    pingServer(address, callback) {
        const xhr = new XMLHttpRequest();
        const start = performance.now(); // More accurate than Date.now()

        xhr.open('GET', `https://${address}/ping`, true);
        xhr.timeout = 5000; // 5 second timeout

        xhr.onreadystatechange = () => {
            if (xhr.readyState === 4) {
                const end = performance.now();
                const pingTime = xhr.status === 200 ? Math.round(end - start) : null;
                callback(pingTime);
            }
        };

        xhr.onerror = () => {
            callback(null);
        };

        xhr.ontimeout = () => {
            callback(null);
        };

        xhr.send();
    }

    updatePingDisplay(element, pingTime, isPopup = false) {
        const pingElement = element.querySelector('.ping-time') || element.querySelector('.ping-display');

        if (!pingElement) return;

        if (pingTime !== null) {
            pingElement.textContent = pingTime + ' ms';
            const pingClass = this.getPingClass(pingTime);

            // Remove all ping classes
            pingElement.classList.remove('ping-green', 'ping-yellow', 'ping-orange', 'ping-red', 'ping-loading');
            pingElement.classList.add(pingClass);

            if (isPopup) {
                // For popup, also update the server item border
                element.classList.remove('ping-green', 'ping-yellow', 'ping-orange', 'ping-red');
                element.classList.add(pingClass);
            }

            return pingTime;
